        m["Based on the documentation, you know the format of the token is:"] = R.string.t_based_on_the_documentation_you_k_333fdb
        m["You also spot this comment in the docs: \"To ensure your security, we use aes-128-ecb throughout our application.\"\n\nManipulate the session tokens you have captured to log in as Sweep with admin privileges."] = R.string.t_you_also_spot_this_comment_in_th_ebe522
